<?php
require_once __DIR__.'/thanh_toan.php';
function approve_cancel(array $u,int $request,bool $approved,int $refund,string $reason): void {
 must(can($u,'DUYET_HUY'),'Không có quyền duyệt hủy.',403);transaction(function()use($u,$request,$approved,$refund,$reason){$r=db_one('SELECT * FROM yeu_cau_huy WHERE id=?',[$request]);must((bool)$r,'Không thấy yêu cầu.');[$h,$x]=lock_contract($r['so_hop_dong']);must(contract_access($u,$h),'Ngoài phạm vi.',403);$r=db_one('SELECT * FROM yeu_cau_huy WHERE id=? FOR UPDATE',[$request]);must($r['trang_thai']==='CHO_DUYET','Yêu cầu đã xử lý.');must($h['trang_thai_hd']!=='HOAN_TAT','Đơn đã bàn giao không thể hủy theo quy trình này.');must($refund>=0&&$refund<=max(0,money_total($h['so_hop_dong'])),'Số tiền duyệt hoàn vượt tiền đã nhận.');valid_text($reason,2000);
 execute('UPDATE yeu_cau_huy SET trang_thai=?,nguoi_duyet_id=?,tien_duoc_hoan=?,ket_qua=?,ngay_duyet=NOW() WHERE id=?',[$approved?'DA_DUYET':'TU_CHOI',$u['id'],$approved?$refund:0,$reason,$request]);if($approved){execute("UPDATE hop_dong SET trang_thai_hd='DA_HUY' WHERE so_hop_dong=?",[$h['so_hop_dong']]);if(in_array($x['trang_thai'],['DANG_GIU','DA_DAT_COC'],true)&&!other_active($x['so_khung_vin'],$h['so_hop_dong']))execute("UPDATE xe SET trang_thai='SAN_SANG_BAN' WHERE so_khung_vin=?",[$x['so_khung_vin']]);}audit('DUYET_HUY','hop_dong',$h['so_hop_dong'],null,['duyet'=>$approved,'hoan'=>$refund]);});
}
function reserve_refund(array $u,int $request,string $original,int $amount,string $key): string {
 must(can($u,'DUYET_HOAN'),'Chưa có quyền hoàn tiền.',403);return transaction(function()use($u,$request,$original,$amount,$key){$req=db_one('SELECT * FROM yeu_cau_huy WHERE id=?',[$request]);must((bool)$req,'Không có yêu cầu hủy.');[$h,$x]=lock_contract($req['so_hop_dong']);must(contract_access($u,$h),'Ngoài phạm vi.',403);$req=db_one('SELECT * FROM yeu_cau_huy WHERE id=? FOR UPDATE',[$request]);must($req['trang_thai']==='DA_DUYET','Chưa duyệt hoàn.');$old=db_one('SELECT ma_hoa_don FROM hoa_don WHERE so_hop_dong=? AND ma_yeu_cau=?',[$h['so_hop_dong'],$key]);if($old)return $old['ma_hoa_don'];$p=db_one('SELECT * FROM hoa_don WHERE ma_hoa_don=? FOR UPDATE',[$original]);must($p&&$p['so_hop_dong']===$h['so_hop_dong']&&$p['loai_giao_dich']==='THU'&&$p['trang_thai']==='SUCCESS','Khoản thu gốc không hợp lệ.');
 $used=(int)db_one("SELECT COALESCE(SUM(so_tien_thu),0) n FROM hoa_don WHERE giao_dich_goc=? AND trang_thai IN ('SUCCESS','CHO_XAC_NHAN')",[$original])['n'];$approvedUsed=(int)db_one("SELECT COALESCE(SUM(so_tien_thu),0) n FROM hoa_don WHERE yeu_cau_huy_id=? AND loai_giao_dich='HOAN_TIEN' AND trang_thai IN ('SUCCESS','CHO_XAC_NHAN')",[$request])['n'];must($amount>0&&$amount<=vnd($p['so_tien_thu'])-$used&&$amount<=(int)$req['tien_duoc_hoan']-$approvedUsed,'Số tiền vượt hạn mức thu gốc hoặc mức đã duyệt.');$id=uid('HT');execute("INSERT INTO hoa_don(ma_hoa_don,so_hop_dong,so_tien_thu,phuong_thuc_tt,nguon_tham_chieu,nguoi_ghi_nhan_id,loai_giao_dich,giao_dich_goc,yeu_cau_huy_id,ma_yeu_cau,noi_dung_thu) VALUES(?,?,?,'CHUYEN_KHOAN','HOAN_THU_CONG',?,'HOAN_TIEN',?,?,?,'Hoàn tiền theo yêu cầu đã duyệt')",[$id,$h['so_hop_dong'],$amount,$u['id'],$original,$request,$key]);audit('TAO_LENH_HOAN','hoa_don',$id);return $id;});
}
function confirm_refund(array $u,string $id,string $source,string $ref,string $when): void { must(can($u,'DUYET_HOAN'),'Không có quyền hoàn.',403);transaction(function()use($u,$id,$source,$ref,$when){$p=db_one('SELECT * FROM hoa_don WHERE ma_hoa_don=?',[$id]);must($p&&$p['loai_giao_dich']==='HOAN_TIEN','Lệnh hoàn không hợp lệ.');[$h,$x]=lock_contract($p['so_hop_dong']);must(contract_access($u,$h),'Ngoài phạm vi.',403);$p=db_one('SELECT * FROM hoa_don WHERE ma_hoa_don=? FOR UPDATE',[$id]);if($p['trang_thai']==='SUCCESS')return;must($p['trang_thai']==='CHO_XAC_NHAN','Lệnh hoàn không còn chờ.');$source='HOAN_'.valid_text($source,90);execute('UPDATE hoa_don SET nguon_tham_chieu=? WHERE ma_hoa_don=?',[$source,$id]);settle_payment($id,vnd($p['so_tien_thu']),valid_text($ref,100),$source,true,valid_date($when));}); }
